INSERT INTO "public"."recipe_steps" ("id", "recipe_card_id", "step_number", "description", "tip", "time_minutes", "image_path", "created_at", "updated_at", "step_image_url", "step_video_url") VALUES
	('f1d7cc29-14ff-40da-9e4c-e29b086e2067', '15135fdf-d062-46ce-9f11-795196ba9355', 1, 'Se agregan todos los ingredientes en una olla a fuego medio', NULL, NULL, NULL, '2026-02-23 20:34:32.443689+00', '2026-02-23 20:34:32.443689+00', NULL, NULL),
	('cfb38b74-300c-4954-a003-913e572bae3e', '15135fdf-d062-46ce-9f11-795196ba9355', 2, 'Cocinar mezclando constantemente para lograr extraer el picante del ají.', NULL, NULL, NULL, '2026-02-23 20:34:32.443689+00', '2026-02-23 20:34:32.443689+00', NULL, NULL),
	('d3b2f0fb-9848-4341-a886-c34d96b20bf0', '15135fdf-d062-46ce-9f11-795196ba9355', 3, 'Se deja enfriar al ambiente antes de empacar al vacío.', NULL, NULL, NULL, '2026-02-23 20:34:32.443689+00', '2026-02-23 20:34:32.443689+00', NULL, NULL),
	('227ac98f-058b-470b-961c-ff3cbcd1c73f', 'e933f2f4-a5dd-405a-a307-4122f4461b06', 1, 'Se llevan todos los ingredientes a una olla y se ponen a fuego medio-bajo hasta que llegue a punto de ebullición.', NULL, NULL, NULL, '2026-02-23 20:49:17.734144+00', '2026-02-23 20:49:17.734144+00', NULL, NULL),
	('e975a852-dcbe-4aee-88ba-c559fd07b686', 'e933f2f4-a5dd-405a-a307-4122f4461b06', 2, 'La preparación se debe dejar en cocción hasta que tenga el espesor indicado.', 'Se debe realizar la prueba de la cuchara para verificar que esté en el espesor indicado.', 30, NULL, '2026-02-23 20:49:17.734144+00', '2026-02-23 20:49:17.734144+00', NULL, NULL),
	('dd2c7d12-b9a0-4450-a459-3b701c4017c6', 'f87e0e4b-098f-406f-952c-657382d72759', 1, 'Se inicia con la limpieza y pelada de la cebolla', NULL, NULL, NULL, '2026-02-26 20:41:34.545562+00', '2026-02-26 20:41:34.545562+00', NULL, NULL),
	('9126ec08-bd59-44d6-981b-b365af47b549', 'f87e0e4b-098f-406f-952c-657382d72759', 2, 'Cada cebolla se corta por mitad y se le realizan cortes en pluma no tan delgados para evitar que se deshaga en la cocción.', NULL, NULL, NULL, '2026-02-26 20:41:34.545562+00', '2026-02-26 20:41:34.545562+00', NULL, NULL),
	('7389ab2f-2b66-4bfd-ac4e-c156d74dd00d', 'f87e0e4b-098f-406f-952c-657382d72759', 3, 'En una olla grande y honda se agrega el azúcar y se deja caramelizar, es importante agitar la olla ocasionalmente de forma circular sin ningún elemento, solo dando vueltas a la olla para evitar que esta se pegue o se queme.', NULL, NULL, NULL, '2026-02-26 20:41:34.545562+00', '2026-02-26 20:41:34.545562+00', NULL, NULL),
	('496ddf98-23fc-4a4c-87c4-7cc44f3fa051', 'f87e0e4b-098f-406f-952c-657382d72759', 4, 'Cuando ya adquiera la consistencia caramelizada y este derrita todo el azúcar se añade la cebolla y sobre ella el vino y el Maggi.', NULL, NULL, NULL, '2026-02-26 20:41:34.545562+00', '2026-02-26 20:41:34.545562+00', NULL, NULL),
	('6311c226-e9f8-42d5-98c2-519232f5028f', 'f87e0e4b-098f-406f-952c-657382d72759', 5, 'Se tapa y se deja cocinar a fuego medio.', NULL, 50, NULL, '2026-02-26 20:41:34.545562+00', '2026-02-26 20:41:34.545562+00', NULL, NULL),
	('483da4c5-befa-45b5-a8af-94056ad83899', 'f87e0e4b-098f-406f-952c-657382d72759', 6, 'Transcurrido el tiempo se apaga y se deja enfriar al ambiente para después porcionar.', NULL, NULL, NULL, '2026-02-26 20:41:34.545562+00', '2026-02-26 20:41:34.545562+00', NULL, NULL);
